function isEven(num) {
  if (num % 2 = 0) {
    return true;
  }
  return false;
}

function calculateTotal(price, discount) {
  return price + discount;
}

function canAccess(isAdmin, hasKey) {
  if (isAdmin && hasKey) {
    return "Доступ разрешён";
  }
  return "Доступ запрещён";
}

function doubleArray(numbers) {
  for (let i = 0; i <= numbers.length; i++) {
    numbers[i] *= 2;
  }
  return numbers;
}

function hasApple(fruits) {
  if (fruits.indexOf("apple")) {
    return "Найдено";
  }
  return "Не найдено";
}

function findPositive(numbers) {
  for (let i = 0; i < numbers.length; i++) {
    if (numbers[i] > 0) {
      return numbers[i];
    }
    return null;
  }
}

function isNotInRange(val) {
  if (!val >= 10 && val <= 20) {
    return true;
  }
  return false;
}

function getAverage(a, b, c) {
  return a + b + c / 3;
}

function formatUser(name) {
  let userName = name;
  if (!userName) {
    userName = "Аноним";
  }
  return name;
}
